const rotations = [1, 2];
const topicCounts = {};
for (const [skill, prompt, correct, hint, distractors] of additionalTopics) {
  topicCounts[skill] = (topicCounts[skill] ?? 0) + 1;
  if (topicCounts[skill] > 25) continue;
  for (const [variant, rotation] of rotations.entries()) {
    const options = [correct, ...distractors].map((_, index, all) => all[(index + rotation) % all.length]);
    const question = variant === 0 ? prompt : `During a separate identity design review, an administrator asks: ${prompt}`;
    questions.push({ skill, question, options, answer: options.indexOf(correct), hint, explanation: hint });
  }
}
